.settings-page *::before,
.settings-page *::after {
	box-sizing: border-box;
}

.settings-header,
.settings-card-heading,
.settings-file-row,
.settings-resource-row {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 12px;
}

.settings-header {
	align-items: flex-start;
	border-bottom: 1px solid
		var(--vscode-panel-border, var(--vscode-editorWidget-border));
	padding-bottom: 10px;
}

.settings-header h1,
.settings-card h2 {
	margin: 0;
	font-weight: 600;
}

.settings-header h1 {
	font-size: 16px;
}

.settings-card h2 {
	font-size: 13px;
}

.settings-card {
	display: flex;
	flex-direction: column;
	gap: 9px;
	border: 1px solid
		var(--vscode-panel-border, var(--vscode-editorWidget-border));
	border-radius: 5px;
	padding: 12px;
	background: var(--vscode-editorWidget-background, transparent);
}

.settings-help,
.settings-summary,
.settings-footer {
	margin: 0;
	color: var(--vscode-descriptionForeground, var(--vscode-foreground));
	font-size: 11px;
	line-height: 1.45;
}

.settings-path {
	display: block;
	overflow-wrap: anywhere;
	padding: 7px 8px;
	border: 1px solid var(--vscode-input-border, var(--vscode-panel-border));
	border-radius: 3px;
	color: var(--vscode-textPreformat-foreground, var(--vscode-foreground));
	background: var(
		--vscode-textCodeBlock-background,
		var(--vscode-input-background)
	);
	font-family: var(--vscode-editor-font-family, monospace);
	font-size: 11px;
}

.settings-button {
	flex: 0 0 auto;
	min-height: 26px;
	border: 1px solid transparent;
	border-radius: 3px;
	padding: 4px 10px;
	cursor: pointer;
	color: var(--vscode-button-foreground);
	background: var(--vscode-button-background);
	font: inherit;
}

.settings-button:hover {
	background: var(--vscode-button-hoverBackground);
}

.settings-button:focus-visible,
.settings-resource-row input:focus-visible {
	outline: 1px solid var(--vscode-focusBorder);
	outline-offset: 2px;
}

.settings-button-secondary {
	color: var(--vscode-button-secondaryForeground, var(--vscode-foreground));
	border-color: var(--vscode-button-border, var(--vscode-panel-border));
	background: var(--vscode-button-secondaryBackground, transparent);
}

.settings-button-secondary:hover {
	background: var(
		--vscode-button-secondaryHoverBackground,
		var(--vscode-toolbar-hoverBackground)
	);
}

.settings-resource-list,
.settings-file-list,
.settings-package-list {
	display: flex;
	flex-direction: column;
	gap: 7px;
}

.settings-resource-row {
	align-items: flex-start;
	padding: 8px 0;
	border-top: 1px solid
		var(--vscode-panel-border, var(--vscode-editorWidget-border));
}

.settings-resource-row:first-child {
	border-top: 0;
}

.settings-resource-copy,
.settings-file-row > div {
	display: flex;
	flex-direction: column;
	gap: 2px;
	min-width: 0;
}

.settings-resource-label {
	font-weight: 600;
}

.settings-resource-row input {
	flex: 0 0 auto;
	width: 14px;
	height: 14px;
	accent-color: var(--vscode-focusBorder);
}

.settings-file-row {
	align-items: center;
	padding: 8px 0;
	border-top: 1px solid
		var(--vscode-panel-border, var(--vscode-editorWidget-border));
}

.settings-file-row:first-child {
	border-top: 0;
}

.settings-package-missing {
	display: flex;
	justify-content: space-between;
	gap: 8px;
	overflow-wrap: anywhere;
	padding: 5px 7px;
	border-left: 2px solid var(--vscode-editorWarning-foreground, #cca700);
	color: var(--vscode-descriptionForeground, var(--vscode-foreground));
	background: var(--vscode-textBlockQuote-background, transparent);
	font-family: var(--vscode-editor-font-family, monospace);
	font-size: 11px;
}

.settings-alert {
	padding: 7px 9px;
	border-radius: 3px;
	line-height: 1.4;
}

.settings-alert-error {
	border: 1px solid var(--vscode-inputValidation-errorBorder, #f14c4c);
	color: var(
		--vscode-inputValidation-errorForeground,
		var(--vscode-foreground)
	);
	background: var(--vscode-inputValidation-errorBackground, transparent);
}

.settings-alert-status {
	border: 1px solid
		var(--vscode-inputValidation-infoBorder, var(--vscode-focusBorder));
	background: var(--vscode-inputValidation-infoBackground, transparent);
}

.settings-footer {
	padding: 4px 1px 10px;
}

.settings-loading {
	justify-content: center;
	color: var(--vscode-descriptionForeground);
}

@media (max-width: 360px) {
	.settings-header,
	.settings-card-heading,
	.settings-file-row {
		align-items: stretch;
		flex-direction: column;
	}

	.settings-button {
		width: 100%;
	}
}

